{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 입장료를 신용카드로 받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제15조제3항에 따르면 공원의 입장료 또는 이용료를 외국환 또는 신용카드로 받을 수 있다. 따라서 입장료를 현금으로 내지 못했더라도 신용카드로 납부할 수 있다. 다만 환율은 서울특별시금고 은행의 전일 최종 현금 매입가를 적용하고, 거스름돈이 있을 경우 10원 미만의 단수는 계산하지 아니한다.",
          "b_ids": "도시공원:제15조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
